<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import api from'../../services/api';import{useAuthStore}from'../../stores/auth'
const auth=useAuthStore(),saving=ref(false),loading=ref(false),passwordOpen=ref(false),changing=ref(false)
const account=reactive({full_name:auth.user?.full_name||'',phone:'',email:''}),patient=reactive({gender:'unknown',birth_date:'',address:'',blood_group:'',allergies:'',medical_history:''}),doctor=reactive({title:'',specialty:'',introduction:'',is_available:true,department_name:''}),password=reactive({current_password:'',new_password:'',new_password_confirm:''})
function err(e:any,fallback:string){const errors=e.response?.data?.errors;if(errors){const first=Object.values(errors)[0] as any;return Array.isArray(first)?first.join('；'):String(first)}return e.response?.data?.detail||fallback}
async function load(){loading.value=true;try{const{data}=await api.get('auth/me/');Object.assign(account,{full_name:data.full_name,phone:data.phone||'',email:data.email||''});if(data.role==='patient')Object.assign(patient,(await api.get('patients/me/')).data);if(data.role==='doctor')Object.assign(doctor,(await api.get('doctors/me/')).data)}finally{loading.value=false}}
async function save(){saving.value=true;try{const{data}=await api.patch('auth/me/',account);auth.user=data;localStorage.setItem('smart_medical_user',JSON.stringify(data));if(data.role==='patient')await api.patch('patients/me/',patient);if(data.role==='doctor')await api.patch('doctors/me/',{title:doctor.title,specialty:doctor.specialty,introduction:doctor.introduction,is_available:doctor.is_available});ElMessage.success('个人资料已保存')}catch(e:any){ElMessage.error(err(e,'保存失败'))}finally{saving.value=false}}
async function changePassword(){if(password.new_password!==password.new_password_confirm){ElMessage.warning('两次输入的新密码不一致');return}changing.value=true;try{await api.post('auth/change-password/',password);ElMessage.success('密码已修改，请重新登录');auth.logout();location.assign(`${import.meta.env.BASE_URL}login`)}catch(e:any){ElMessage.error(err(e,'密码修改失败'))}finally{changing.value=false}}
onMounted(load)
</script>
<template><section v-loading="loading"><div class="page-heading"><div><h1>个人中心</h1><p>维护账户联系方式与角色专属资料</p></div><el-button @click="passwordOpen=true">修改密码</el-button></div><el-card class="profile-card"><h3>账户信息</h3><el-form label-position="top"><el-row :gutter="14"><el-col :md="12"><el-form-item label="姓名"><el-input v-model="account.full_name"/></el-form-item></el-col><el-col :md="12"><el-form-item label="手机号码"><el-input v-model="account.phone"/></el-form-item></el-col><el-col :md="24"><el-form-item label="电子邮箱"><el-input v-model="account.email"/></el-form-item></el-col></el-row><template v-if="auth.user?.role==='patient'"><el-divider content-position="left">健康档案</el-divider><el-row :gutter="14"><el-col :md="12"><el-form-item label="性别"><el-select v-model="patient.gender" style="width:100%"><el-option label="男" value="male"/><el-option label="女" value="female"/><el-option label="其他" value="other"/><el-option label="未填写" value="unknown"/></el-select></el-form-item></el-col><el-col :md="12"><el-form-item label="出生日期"><el-date-picker v-model="patient.birth_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item></el-col><el-col :md="12"><el-form-item label="血型"><el-input v-model="patient.blood_group"/></el-form-item></el-col><el-col :md="12"><el-form-item label="地址"><el-input v-model="patient.address"/></el-form-item></el-col><el-col :md="12"><el-form-item label="过敏史"><el-input v-model="patient.allergies" type="textarea" :rows="3"/></el-form-item></el-col><el-col :md="12"><el-form-item label="既往病史"><el-input v-model="patient.medical_history" type="textarea" :rows="3"/></el-form-item></el-col></el-row></template><template v-if="auth.user?.role==='doctor'"><el-divider content-position="left">医师资料</el-divider><el-form-item label="所属科室"><el-input v-model="doctor.department_name" disabled/></el-form-item><el-row :gutter="14"><el-col :md="12"><el-form-item label="职称"><el-input v-model="doctor.title"/></el-form-item></el-col><el-col :md="12"><el-form-item label="专业方向"><el-input v-model="doctor.specialty"/></el-form-item></el-col></el-row><el-form-item label="个人介绍"><el-input v-model="doctor.introduction" type="textarea" :rows="4"/></el-form-item><el-switch v-model="doctor.is_available" active-text="可接诊" inactive-text="暂停接诊"/></template><div style="margin-top:20px"><el-button type="primary" :loading="saving" @click="save">保存修改</el-button></div></el-form></el-card><el-dialog v-model="passwordOpen" title="修改密码" width="min(480px,94vw)"><el-form label-position="top"><el-form-item label="当前密码"><el-input v-model="password.current_password" type="password" show-password/></el-form-item><el-form-item label="新密码"><el-input v-model="password.new_password" type="password" show-password/></el-form-item><el-form-item label="确认新密码"><el-input v-model="password.new_password_confirm" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="passwordOpen=false">取消</el-button><el-button type="primary" :loading="changing" @click="changePassword">修改并退出</el-button></template></el-dialog></section></template>
